// Shared teaching content for classroom steps and independent reading.
// Numerical scenarios are invented teaching data; selected papers cover only the mapped parts.
const ids = (requirement, ...numbers) => numbers.map(number => `S7.${String(requirement).padStart(2, '0')}.A${String(number).padStart(2, '0')}`);
const table = (headers, rows) => ({ headers, rows });
const step = (title, body, extra = {}) => ({ title, body, ...extra });
const worked = (title, setup, steps, conclusion) => ({ title, setup, steps, conclusion });
const image = (file, alt, caption) => ({ asset: `/assets/course-v3/section-7/${file}`, alt, caption });

export const section7PaperObjectives = {
  E051: ids(2, 2),
  E052: [...ids(1, 2), ...ids(2, 2)],
  E053: [...ids(1, 2), ...ids(3, 1, 2)],
  E054: [...ids(4, 1), ...ids(5, 1, 2, 4, 5)],
  E055: ids(6, 2, 3),
  E7D01: ids(5, 3, 4),
  E7D02: ids(6, 3),
  E7D03: [...ids(3, 1), ...ids(6, 3)],
};

